    type WatchSchemaStream =
        Pin<Box<dyn tokio_stream::Stream<Item = Result<SchemaEvent, Status>> + Send>>;

    async fn get_schema(
        &self,
        request: TonicRequest<GetSchemaRequest>,
    ) -> Result<TonicResponse<SchemaResponse>, Status> {
        let context = request
            .extensions()
            .get::<TraceContext>()
            .cloned()
            .unwrap_or_else(|| TraceContext::from_tonic_metadata(request.metadata()));

        let schema_json = self.loader.get().await.to_string();
        let mut response = TonicResponse::new(SchemaResponse {
            schema_json,
            trace_id: context.trace_id.clone(),
            footprint: context.footprint.clone(),
        });
        inject_trace_metadata(&mut response, &context);
        Ok(response)
    }

    async fn watch_schema(
        &self,
        _request: TonicRequest<WatchSchemaRequest>,
    ) -> Result<TonicResponse<Self::WatchSchemaStream>, Status> {
        let mut reload_rx = self.loader.reload_tx().subscribe();
        let loader = self.loader.clone();

        let initial = loader.get().await;
        let stream = stream! {
            yield Ok(SchemaEvent {
                schema_json: initial.to_string(),
                event_type: "initial".to_string(),
            });

            while let Ok(SchemaReloadEvent { event_type }) = reload_rx.recv().await {
                let schema_json = loader.get().await.to_string();
                yield Ok(SchemaEvent {
                    schema_json,
                    event_type,
                });
            }
        };

        Ok(TonicResponse::new(Box::pin(stream)))
    }
}

fn inject_trace_metadata<T>(response: &mut TonicResponse<T>, context: &TraceContext) {
    if let (Ok(trace_id), Ok(footprint)) = (context.trace_id.parse(), context.footprint.parse()) {
        response
            .metadata_mut()
            .insert("x-ghostbridge-trace-id", trace_id);
        response
            .metadata_mut()
            .insert("x-ghostbridge-footprint", footprint);
    }
}

/// Assemble the gRPC service set for the zeroclaw bridge.
///
/// The full backplane surface (StateSync, PluginService, DbusPassthrough,
/// OvsdbMirror, RuntimeMirror, EventChainService, ComponentRegistry, Mail,
/// Privacy, Registration, McpService, ChatService, reflection) comes from the
/// shared [`build_operation_routes`] — identical to what `run_grpc_server` mounts
/// on op-dbus :50051, so reflection never advertises an unmounted service. On top
/// of that the zeroclaw bridge adds its endpoint-specific `ZeroclawService`
/// (plugin-owned schema get/watch).
///
/// Every container shares this one surface over `container.sock`; the assistant
/// container is provisioned exactly like the others (its socket created via the
/// unix-socket plugin's createsocket through PluginService, not a raw Incus proxy
/// device).
fn build_routes(loader: Arc<SchemaLoader>, server: OperationGrpcServer) -> tonic::service::Routes {
    let zeroclaw_svc = tonic_web::enable(ZeroclawServiceServer::new(ZeroclawGrpcService { loader }));
    build_operation_routes(server).add_service(zeroclaw_svc)
}

/// Build the axum `Router` that serves the gRPC service over HTTP/gRPC-Web.
pub fn build_axum_app(loader: Arc<SchemaLoader>, server: OperationGrpcServer) -> Router {
    let cors = CorsLayer::new()
        .allow_origin(Any)
        .allow_methods(Any)
        .allow_headers(Any);

    build_routes(loader, server)
        .into_axum_router()
        .layer(cors)
        .layer(GhostbridgeTraceLayer::new())
}

/// Build the tonic `Routes` used for the native-gRPC Unix socket side.
fn build_tonic_routes(
    loader: Arc<SchemaLoader>,
    server: OperationGrpcServer,
) -> tonic::service::Routes {
    build_routes(loader, server)
}

/// Run the zeroclaw Axum host.
///
/// Returns only when both listeners exit (which should not happen under normal
/// operation).
pub async fn run_zeroclaw_server(config: ServerConfig) -> anyhow::Result<()> {
    let loader = Arc::new(SchemaLoader::new(&config.schema_path)?);

    // Channel for D-Bus-triggered rebind requests. Only `SchemaPath` changes are
    // applied live; `BindAddr` changes are recorded and honored on the next
    // restart.
    let (rebind_tx, mut rebind_rx) = mpsc::channel::<String>(4);

    // D-Bus object for runtime configuration.
    let dbus_object = ZeroclawAxumHostObject::new(loader.clone(), rebind_tx)?;
    let _dbus_connection = register_zeroclaw_host_object(dbus_object).await?;

    // SIGHUP reload watcher.
    let _sighup_handle = loader.clone().watch_sighup();

    // PluginService (PluginService.CallMethod) backed by the authoritative
    // MutationEngine. This is how createunixsocket is invoked: a CallMethod with
    // plugin_id="unix_socket" routes through MutationEngine.mutate →
    // UnixSocketPlugin::create_unix_socket. The sled identity is resolved as
    // the actor_id inside mutate when the caller omits it.
    let event_chain = Arc::new(tokio::sync::RwLock::new(
        op_state_store::EventChain::new(op_state_store::ChainConfig::default()),
    ));
    let ovsdb = Arc::new(op_network::rovs_proxy::OvsdbDbusClient::new());
    let nonnet = Arc::new(op_jsonrpc::nonnet::NonNetDb::new());
    let mutation_engine = Arc::new(MutationEngine::new(event_chain, ovsdb, nonnet));
    let operation_server = OperationGrpcServer::new(mutation_engine);
    // Attach the semantic shuttle for parity with run_grpc_server so
    // SearchSemanticTrace behaves identically on both endpoints (best-effort:
    // if Qdrant is unavailable the method returns failed_precondition).
    let operation_server = match op_cognitive_mcp::QdrantSemanticShuttle::new().await {
        Ok(shuttle) => operation_server.with_semantic_shuttle(Arc::new(shuttle)),
        Err(error) => {
            tracing::warn!(%error, "semantic shuttle unavailable; SearchSemanticTrace will return failed_precondition");
            operation_server
        }
    };

    // Unix socket listener for native gRPC.
    let unix_socket = config.unix_socket.clone();
    if let Some(parent) = unix_socket.parent() {
        let _ = std::fs::create_dir_all(parent);
    }
    let _ = std::fs::remove_file(&unix_socket);
    let unix_listener = tokio::net::UnixListener::bind(&unix_socket)?;
    info!(path = %unix_socket.display(), "zeroclaw native gRPC listening on Unix socket");

    let unix_incoming = tokio_stream::wrappers::UnixListenerStream::new(unix_listener);

    // accept_http1(true): tonic-web serves gRPC-Web over HTTP/1.1, which is what
    // browsers (and xray's tls-h1 fallback forwarding to this socket) speak. Without
    // it the socket is h2-only and rejects browser gRPC-Web. Matches the TCP/axum side.
    let tonic_server = tonic::transport::Server::builder()
        .accept_http1(true)
        .add_routes(build_tonic_routes(loader.clone(), operation_server.clone()))
        .serve_with_incoming(unix_incoming);

    // TCP listener for HTTP + gRPC-Web.
    let bind_addr: SocketAddr = config.bind_addr.parse()?;
    let tcp_listener = tokio::net::TcpListener::bind(bind_addr).await?;
    info!(addr = %bind_addr, "zeroclaw HTTP/gRPC-Web listening on TCP");

    let axum_app = build_axum_app(loader.clone(), operation_server);
    let tcp_server = axum::serve(tcp_listener, axum_app);

    // Rebind task: when a new bind address is requested, restart the TCP server.
    // The current implementation starts the initial TCP server; subsequent
    // rebinds require a restart to keep the listener lifecycle simple and safe.
    let rebind_task = tokio::spawn(async move {
        while let Some(new_bind) = rebind_rx.recv().await {
            info!(new_bind = %new_bind, "D-Bus rebind request received; will be honored on next restart");
        }
    });

    let (unix_result, tcp_result) = tokio::join!(tonic_server, tcp_server);
    let _ = rebind_task.await;
    unix_result.map_err(|e| anyhow::anyhow!("Unix server error: {}", e))?;
    tcp_result.map_err(|e| anyhow::anyhow!("TCP server error: {}", e))
}

//! 🟢 🛷 The Shuttle — gRPC Bridge Binary
//!
//! Zero-trust gRPC gateway enforcing the Absolute Base rule via
//! GhostbridgeInterceptor. Reads the IdentitySled from shared memory
//! (/dev/shm/plugin_schema.dat) and rejects any request whose footprint
//! does not match the current Strike/Etch.
//!
//! Design:
//!   - Does NOT write the sled; the MutationEngine or A.N.N.A. Scribe does.
//!   - If no valid sled exists, all inbound requests are rejected.
//!   - Bind address defaults to 127.0.0.1:18789 (Xray redirect target).

use std::net::SocketAddr;
use std::sync::Arc;

use op_grpc_bridge::{grpc_server::run_grpc_server, mutation_engine::MutationEngine};
use op_jsonrpc::nonnet::NonNetDb;
use op_network::rovs_proxy::OvsdbDbusClient;
use op_state_store::{ChainConfig, EventChain};
use tokio::sync::RwLock;
use tonic::transport::Identity;

/// Load TLS identity from env vars or auto-generate a self-signed cert.
/// Env: GRPC_TLS_CERT (PEM), GRPC_TLS_KEY (PEM). If both absent, generates one.
fn load_tls_identity() -> Option<Identity> {
    let cert_pem = std::env::var("GRPC_TLS_CERT").ok();
    let key_pem = std::env::var("GRPC_TLS_KEY").ok();

    match (cert_pem, key_pem) {
        (Some(cert), Some(key)) => {
            tracing::info!("TLS identity loaded from GRPC_TLS_CERT/GRPC_TLS_KEY env vars");
            Some(Identity::from_pem(cert, key))
        }
        _ => {
            let ck = rcgen::generate_simple_self_signed(vec![
                "localhost".to_string(),
                "ghostbridge.tech".to_string(),
                "3tched.com".to_string(),
            ])
            .expect("failed to generate self-signed TLS cert");
            let cert_pem = ck.cert.pem();
            let key_pem = ck.key_pair.serialize_pem();
            tracing::info!("TLS identity auto-generated (self-signed for localhost, ghostbridge.tech, 3tched.com)");
            Some(Identity::from_pem(cert_pem, key_pem))
        }
    }
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::from_default_env()
                .add_directive("op_grpc_bridge=info".parse()?)
                .add_directive("info".parse()?),
        )
        .init();

    // ── Build MutationEngine (authoritative mutation pipeline) ─────────────────
    let event_chain = Arc::new(RwLock::new(EventChain::new(ChainConfig::default())));
    let ovsdb = Arc::new(OvsdbDbusClient::new());
    let nonnet = Arc::new(NonNetDb::new());
    let mutation_engine = Arc::new(MutationEngine::new(event_chain, ovsdb, nonnet));

    // ── Bind address ─────────────────────────────────────────────────────────
    // Per spec: Xray redirects gRPC traffic to 127.0.0.1:18789.
    let addr: SocketAddr = std::env::var("GRPC_BIND")
        .unwrap_or_else(|_| "127.0.0.1:18789".to_string())
        .parse()
        .expect("GRPC_BIND must be a valid socket address");

    // ── TLS identity ────────────────────────────────────────────────────────
    let tls_identity = load_tls_identity();

    tracing::info!(%addr, "The Shuttle gRPC bridge starting");
    tracing::info!(
        "GhostbridgeInterceptor active — requests require X-Ghostbridge-Footprint + X-Ghostbridge-Trace-ID"
    );

    run_grpc_server(addr, mutation_engine, None, tls_identity).await?;
    Ok(())
}

//! D-Bus object for the zeroclaw Axum host.
//!
//! Exposes `/org/opdbus/v1/services/zeroclaw_axum_host` with the runtime
//! configuration properties required by the spec. Writes to `BindAddr` or
//! `SchemaPath` trigger a reload signal; the server task picks it up and
//! reconfigures without restarting the process.

use std::sync::Arc;

use tokio::sync::{mpsc, RwLock};
use tracing::{info, warn};

use crate::schema_loader::SchemaLoader;

const DEFAULT_BIND_ADDR: &str = "0.0.0.0:8090";

/// D-Bus-facing configuration object for the zeroclaw Axum host.
#[derive(Clone)]
pub struct ZeroclawAxumHostObject {
    bind_addr: Arc<RwLock<String>>,
    schema_path: Arc<RwLock<String>>,
    reload_interval_secs: Arc<RwLock<u32>>,
    loader: Arc<SchemaLoader>,
    rebind_tx: mpsc::Sender<String>,
}

impl ZeroclawAxumHostObject {
    pub fn new(loader: Arc<SchemaLoader>, rebind_tx: mpsc::Sender<String>) -> anyhow::Result<Self> {
        let initial_path = loader.path().to_string_lossy().to_string();
        Ok(Self {
            bind_addr: Arc::new(RwLock::new(DEFAULT_BIND_ADDR.to_string())),
            schema_path: Arc::new(RwLock::new(initial_path)),
            reload_interval_secs: Arc::new(RwLock::new(0)),
            loader,
            rebind_tx,
        })
    }

    /// Read the current TCP bind address.
    async fn bind_addr_value(&self) -> String {
        self.bind_addr.read().await.clone()
    }

    /// Read the current plugin-owned schema file path.
    async fn schema_path_value(&self) -> String {
        self.schema_path.read().await.clone()
    }

    /// Read the current periodic reload interval in seconds.
    async fn reload_interval_value(&self) -> u32 {
        *self.reload_interval_secs.read().await
    }
}

#[zbus::interface(name = "org.opdbus.v1.ZeroclawAxumHost")]
impl ZeroclawAxumHostObject {
    #[zbus(property)]
    async fn bind_addr(&self) -> String {
        self.bind_addr_value().await
    }

    #[zbus(property)]
    async fn set_bind_addr(&self, value: String) {
        let mut addr = self.bind_addr.write().await;
        *addr = value.clone();
        drop(addr);
        info!(subid = "mut.service.zeroclaw-axum-host.reload@v1", new_bind = %value, "BindAddr changed; signaling rebind");
        if let Err(e) = self.rebind_tx.send(value).await {
            warn!(error = %e, "failed to send rebind request");
        }
    }

    #[zbus(property)]
    async fn schema_path(&self) -> String {
        self.schema_path_value().await
    }

    #[zbus(property)]
    async fn set_schema_path(&self, value: String) {
        let mut path = self.schema_path.write().await;
        *path = value.clone();
        drop(path);
        self.loader.set_path(value.clone());
        info!(subid = "mut.service.zeroclaw-axum-host.reload@v1", new_path = %value, "SchemaPath changed; reloading");
        if let Err(e) = self.loader.reload().await {
            warn!(error = %e, "schema path reload failed");
            self.loader.set_health_status(e.to_string()).await;
        }
    }

    #[zbus(property)]
    async fn reload_interval_secs(&self) -> u32 {
        self.reload_interval_value().await
    }

    #[zbus(property)]
    async fn set_reload_interval_secs(&self, value: u32) {
        let mut interval = self.reload_interval_secs.write().await;
        *interval = value;
    }

    #[zbus(property)]
    async fn health_status(&self) -> String {
        self.loader.health_status().await
    }
}

/// Register the zeroclaw Axum host object on the system bus.
pub async fn register_zeroclaw_host_object(
    object: ZeroclawAxumHostObject,
) -> anyhow::Result<zbus::Connection> {
    let connection = zbus::Connection::system().await?;
    connection
        .object_server()
        .at("/org/opdbus/v1/services/zeroclaw_axum_host", object)
        .await?;
    info!("registered /org/opdbus/v1/services/zeroclaw_axum_host");
    Ok(connection)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn should_expose_dbus_properties() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("zeroclaw.json");
        std::fs::write(&path, r#"{"name":"zeroclaw"}"#).unwrap();

        let loader = Arc::new(SchemaLoader::new(&path).unwrap());
        let (rebind_tx, _rebind_rx) = mpsc::channel(1);
        let obj = ZeroclawAxumHostObject::new(loader, rebind_tx).unwrap();

        assert_eq!(obj.bind_addr_value().await, "0.0.0.0:8090");
        assert_eq!(obj.schema_path_value().await, path.to_string_lossy());
        assert_eq!(obj.reload_interval_value().await, 0);
        assert_eq!(obj.health_status().await, "ok");
    }
}

